def decode(encoded: str, original: str, message: str) -> str:
    # Step 1: Build the mapping from encoded letters to their original letters
    mapping = {}
    for i, c in enumerate(encoded):
        if c not in mapping:
            mapping[c] = original[i]
        else:
            return "Failed"

    # Step 2: Use the mapping to decode the encrypted message
    decoded = ""
    for c in message:
        if c in mapping:
            decoded += mapping[c]
        else:
            return "Failed"

    return decoded

def largest_prime_factor(n: int) -> int:
    if n < 2:
        return n  # base case for 1 and 0, which have no factors
    for i in range(2, int(n ** 0.5) + 1):  # iterate through potential factors up to the square root of 'n'
        if n % i == 0:
            return largest_prime_factor(n // i)  # recursive call with 'n' divided by 'i'
    return n  # if no factors were found, 'n' is a prime number and is returned as the largest prime factor

