def preorder_traversal(inorder: str, postorder: str) -> str:
    # Create a dict to map the inorder traversal to the postorder traversal
    inorder_to_post = {inorder[i]: postorder[i] for i in range(len(inorder))}

    # Create a stack to store the nodes of the binary tree
    stack = []

    # Iterate through the postorder traversal
    for char in postorder:
        # If the char is not in the inorder traversal, it must be a leaf node
        if char not in inorder:
            stack.append(char)
        # If the char is in the inorder traversal, it must be a internal node
        else:
            # Pop the internal node from the stack until we find the parent of the char
            while stack and stack[-1] != inorder_to_post[char]:
                stack.pop()
            # Push the internal node to the stack
            stack.append(inorder_to_post[char])

    # Return the preorder traversal of the binary tree
    return "".join(stack)

