def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Calculate the maximum volume that can be occupied by any subset of the given items
    max_vol = max(volumes)

    # Initialize a 2D array to store the results of the dynamic programming approach
    dp = [[0] * (n + 1) for i in range(n + 1)]

    # Loop through each item and calculate the maximum volume that can be occupied by a subset starting with the current item
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if i == j:
                dp[i][j] = volumes[i - 1]
            elif volumes[i - 1] >= dp[i - 1][j]:
                dp[i][j] = dp[i - 1][j]
            else:
                dp[i][j] = max(dp[i - 1][j], volumes[i - 1])

    # Return the difference between the box's total capacity and the maximum occupied volume
    return V - max_vol if max_vol >= V else 0

