def minimum_cost_to_merge_fruits(fruit_counts: List[int]) -> int:

    min_heap = PriorityQueue()

    for fruit_id, count in enumerate(fruit_counts):
        min_heap.put(count, fruit_id)

    total_cost = 0

    while not min_heap.isEmpty():
        current_count = min_heap.get()
        # Merge heaps with smallest total count
        if not min_heap.isEmpty() and min_heap.peek() < current_count:
            total_cost += min_heap.get() + current_count
        else:
            total_cost += current_count

    return total_cost

